def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A diagonal with at least two cells of the same color is extended
    # from its ends until it reaches the grid edge or another color.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == 1:
                    continue
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                # Walk the existing segment to its far endpoint.
                er, ec = r, c
                while (0 <= er + dr < h and 0 <= ec + dc < w
                       and grid[er + dr][ec + dc] == color):
                    er += dr
                    ec += dc

                # Extend from both ends of the segment.
                for sr, sc, step_r, step_c in (
                    (r, c, -dr, -dc),
                    (er, ec, dr, dc),
                ):
                    rr, cc = sr + step_r, sc + step_c
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != 1:
                            break
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c

    return out
